code.source:
#include <iostream>
#include <string>
using namespace std;

int main() {
    string word = "Goa";
    for (char c : word) {
        cout << c << endl;
    }
    for (int n : {10, 20, 30}) {
        cout << n << endl;
    }
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

int main() {
    string word = "Konkani";
    int vowels = 0;
    for (char c : word) {
        if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') {
            vowels++;
        }
    }
    cout << "Vowels: " << vowels << endl;
    return 0;
}

